def student_lesson(topic:str,audience:str):
    easy={
        "AI 개념과 첫걸음":"AI는 사람처럼 살아가는 존재가 아니라, 사람이 준 자료와 규칙을 바탕으로 특정 일을 도와주는 컴퓨터 기술입니다.",
        "머신러닝과 딥러닝":"컴퓨터가 많은 예를 보고 공통점을 찾아 다음 일을 더 잘하도록 배우는 방법입니다.",
        "GPT와 ChatGPT":"GPT는 글을 이해하고 만드는 데 쓰이는 AI 모델이고, ChatGPT는 그 모델을 사람이 대화식으로 쉽게 쓰도록 만든 서비스입니다.",
    }.get(topic,f"{topic}을(를) 처음 접하는 사람도 따라 할 수 있도록 생활 속 예시부터 시작합니다.")
    return {"제목":topic,"대상":audience,"오늘의 이야기":f"우리가 일상에서 ‘{topic}’을 만났다고 생각해 봅시다. 어려운 말보다 먼저, 이것이 내 생활에서 어떤 도움을 줄 수 있는지 살펴봅니다.","오늘 배울 것":["무엇인지 한 문장으로 설명하기","직접 한 번 사용해 보기","AI의 결과가 맞는지 확인하기"],"쉽게 알아보기":easy,"따라하기":["AI 도구를 엽니다.","오늘 주제에 맞는 짧은 질문을 입력합니다.","이해되지 않는 표현을 더 쉽게 설명해 달라고 요청합니다."],"내가 해보기":"내 생활과 관련된 질문 하나를 직접 만들어 입력해 보세요.","결과 확인":"이름·숫자·날짜·기능처럼 확인 가능한 내용은 공식 자료나 믿을 만한 출처와 비교합니다.","오늘의 한 줄":"AI는 정답 기계가 아니라, 질문하고 확인하면서 사용하는 도구입니다."}

def teacher_lesson(topic:str,audience:str):
    return {"제목":topic,"대상":audience,"수업 목표":["전문용어 없이 핵심 개념을 설명한다.","강사 시범 후 학습자가 직접 실행한다.","결과 검증 습관을 익히게 한다."],"시간 배분":{"개념설명":18,"실기와실습":144,"정리와점검":18,"총시간":180},"강사 멘트":f"오늘은 {topic}을 외우는 시간이 아니라, 직접 써 보면서 어디에 도움이 되는지 확인해 보겠습니다.","설명 원칙":["전문용어보다 생활 비유를 먼저 사용","한 번에 기능을 많이 소개하지 않음","설명 18분을 넘기지 않고 실습으로 전환"],"지도 포인트":"AI가 틀릴 수 있음을 반복해서 확인시키고, 개인정보·저작권·출처 확인을 함께 지도합니다."}
